package io.github.ningpp.compat;

/** Replacement for System.DirectoryServices.ActiveDirectory.ActiveDirectoryObjectExistsException (generated by CSharpToJava converter). */
public class ActiveDirectoryObjectExistsException extends RuntimeException {
    private int hresult;
    public ActiveDirectoryObjectExistsException() { super(); }
    public ActiveDirectoryObjectExistsException(String message) { super(message); }
    public ActiveDirectoryObjectExistsException(String message, Throwable cause) { super(message, cause); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
